+type Args = Record<string, string>;
+function parseArgs(argv: string[]): Args {
+  const out: Args = {};
+  for (let i = 0; i < argv.length; i++) {
+    const a = argv[i]!;
+    if (a.startsWith("--")) {
+      const next = argv[i + 1];
+      if (next == null || next.startsWith("--")) out[a.slice(2)] = "1";
+      else { out[a.slice(2)] = next; i++; }
+    }
+  }
+  return out;
+}
