+  const closed = new Promise<void>((resolve, reject) => {
+    ws.on("close", () => resolve());
+    ws.on("error", (e) => {
+      console.error(`bench-stream: baguette stream WebSocket ${url} failed: ${e.message}`);
+      reject(e);
+    });
+  });
