+    const color = classify(r, g, b);
+    const changed = last !== "" && color !== last && (color === "red" || color === "blue");
+    if (color === "red" || color === "blue") last = color;
+    clientFrames.push({ t, bytes: 0, changed, color });
+    if (!clientFirstFrameAt) clientFirstFrameAt = t;
