+      if (c === probe || c.width * c.height < 200_000) return;
+      const t = now();
+      const d = this.getImageData(c.width >> 1, c.height >> 1, 1, 1).data;
+      (window as any).__benchFrame(t, d[0], d[1], d[2]);
+    } as any;
