+        seen.set(img, img.currentSrc);
+        (orig as any).call(pctx, img, img.naturalWidth >> 1, img.naturalHeight >> 1, 1, 1, 0, 0, 1, 1);
+        const d = pctx.getImageData(0, 0, 1, 1).data;
